import{u as n,j as e,L as a}from"./index-BH11_uNN.js";import{L as l,a as t}from"./LegalDoc-5Ee53fdQ.js";import"./Seo-C2apjei6.js";import"./cloudinary-C4FyQwY9.js";const o="grupoinmobiliario3i.ec@gmail.com",i=e.jsx("a",{href:`mailto:${o}`,className:"text-accent underline",children:o}),s="text-accent underline",c={seoTitle:"Términos y condiciones",seoDesc:"Condiciones de uso de grupo3i.com: información de proyectos y precios, compras, Refiere y gana, desarrolladoras aliadas y responsabilidad.",title:"Términos y condiciones",updated:"Última actualización: octubre de 2026",intro:"Estos términos regulan el uso de grupo3i.com. Al usar el sitio los aceptas. Si algo no queda claro, escríbenos antes de usarlo.",sections:[{title:"1. Quiénes somos",body:[e.jsxs(e.Fragment,{children:["Grupo 3i es un grupo inmobiliario con operaciones en Manglaralto, provincia de Santa Elena, Ecuador. Contacto: ",i," o WhatsApp +593 98 487 5050."]})]},{title:"2. La información del sitio es referencial",body:["Publicamos precios, disponibilidad, medidas, fotos, renders, proyecciones y cuotas con el mayor cuidado, pero son referenciales y pueden cambiar sin aviso. Un lote puede venderse mientras lo estás mirando.","Las cifras de plusvalía, rentabilidad o retorno son estimaciones y no garantizan resultados. Las medidas y linderos definitivos son los que constan en la escritura.","Nada de lo publicado es una oferta vinculante. Una compra solo queda firme con la firma del contrato correspondiente (reserva, promesa de compraventa o escritura), que prevalece sobre lo que diga el sitio."]},{title:"3. Proyectos de desarrolladoras aliadas",body:["Algunos proyectos son de desarrolladoras aliadas. Antes de publicarlos revisamos sus documentos legales básicos y, si pasan la revisión, muestran el sello «Verificado por Grupo 3i».","El sello significa que revisamos esos documentos a la fecha de la revisión; no reemplaza tu propia revisión legal ni convierte a Grupo 3i en vendedor o garante del proyecto. La desarrolladora es la responsable de su proyecto, de la información que publica y del contrato que firma contigo."]},{title:"4. Compras y reservas",body:["Cada producto inmobiliario se rige por su propio contrato, que detalla el precio, la forma de pago, los plazos y las condiciones de desistimiento.","Los planes de financiamiento directo (entrada y cuotas) se pactan por escrito en ese contrato."]},{title:"5. Refiere y gana",body:[e.jsx(e.Fragment,{children:"El programa de referidos tiene su propio reglamento de Refiere y gana, que forma parte de estos términos. Quien se registra lo acepta al crear su cuenta y lo tiene siempre disponible en su oficina virtual."})]},{title:"6. Tu cuenta",body:["Si creas una cuenta (Refiere y gana o portal de desarrolladoras), te comprometes a dar datos verdaderos y a cuidar tu contraseña. Eres responsable de lo que se haga con tu cuenta. Podemos suspender cuentas con datos falsos, uso fraudulento o que incumplan estos términos."]},{title:"7. Uso correcto del sitio",body:[e.jsx(t,{items:["No copies ni reutilices los textos, fotos, planos, mapas o datos del sitio con fines comerciales sin autorización escrita.","No intentes acceder a áreas privadas, extraer información de forma automatizada ni afectar el funcionamiento del sitio.","No publiques enlaces de referido con información engañosa sobre los proyectos."]}),"Las marcas Grupo 3i, Montañita View e Ibiza Condohotel, y el contenido del sitio, pertenecen a Grupo 3i o a sus aliados."]},{title:"8. Responsabilidad",body:["Hacemos lo posible para que el sitio funcione y la información esté al día, pero no podemos garantizar que esté siempre disponible o libre de errores. No respondemos por decisiones tomadas solo con base en la información referencial del sitio, sin firmar el contrato correspondiente, ni por el contenido de sitios de terceros a los que enlazamos."]},{title:"9. Privacidad",body:[e.jsxs(e.Fragment,{children:["Cómo tratamos tus datos está en la ",e.jsx(a,{to:"/privacidad",className:s,children:"política de privacidad y cookies"}),"."]})]},{title:"10. Ley aplicable y cambios",body:["Estos términos se rigen por las leyes del Ecuador. Cualquier controversia se resolverá ante los jueces competentes de la provincia de Santa Elena, salvo que la ley de protección al consumidor te dé otro fuero.","Podemos actualizar estos términos; la versión vigente es la publicada en esta página, con su fecha."]}]},d={seoTitle:"Terms of use",seoDesc:"Terms of use for grupo3i.com: project and pricing information, purchases, Refer & Earn, partner developers and liability.",title:"Terms of use",updated:"Last updated: October 2026",intro:"These terms govern your use of grupo3i.com. By using the site, you agree to them. If anything is unclear, please get in touch before using it.",sections:[{title:"1. Who we are",body:[e.jsxs(e.Fragment,{children:["Grupo 3i is a real estate group operating in Manglaralto, Santa Elena province, Ecuador. Contact: ",i," or WhatsApp +593 98 487 5050."]})]},{title:"2. Site information is for reference only",body:["We take great care with the prices, availability, dimensions, photos, renderings, projections and payment plans we publish, but they’re for reference only and may change without notice. A lot may sell while you’re looking at it.","Appreciation, yield and return figures are estimates, not guarantees. Final dimensions and boundaries are those stated in the deed.","Nothing on this site is a binding offer. A purchase is only final once the relevant contract is signed (reservation, purchase agreement or deed), and that contract takes precedence over anything on the site."]},{title:"3. Partner developers’ projects",body:["Some projects belong to partner developers. Before listing them, we review their core legal documents; if they pass, they carry the “Verified by Grupo 3i” seal.","The seal means we reviewed those documents as of the review date. It doesn’t replace your own legal due diligence, and it doesn’t make Grupo 3i the seller or guarantor of the project. The developer is responsible for its project, the information it publishes and the contract it signs with you."]},{title:"4. Purchases and bookings",body:["Each real estate product is governed by its own contract, which sets out the price, payment terms, timeline and cancellation conditions.","Direct financing plans (down payment and monthly payments) are agreed in writing in that contract."]},{title:"5. Refer & Earn",body:[e.jsx(e.Fragment,{children:"The referral program has its own Refer & Earn program rules, which are part of these terms. Members accept them when they sign up and can always find them in their Virtual Office."})]},{title:"6. Your account",body:["If you create an account (Refer & Earn or the developer portal), you agree to provide accurate information and keep your password safe. You’re responsible for activity on your account. We may suspend accounts with false information, fraudulent use or that break these terms."]},{title:"7. Using the site",body:[e.jsx(t,{items:["Don’t copy or reuse the site’s text, photos, plans, maps or data for commercial purposes without written permission.","Don’t try to access private areas, scrape data or disrupt the site.","Don’t share referral links with misleading claims about our projects."]}),"The Grupo 3i, Montañita View and Ibiza Condohotel names and the site’s content belong to Grupo 3i or its partners."]},{title:"8. Liability",body:["We do our best to keep the site running and up to date, but we can’t guarantee it will always be available or error-free. We’re not responsible for decisions made solely on the site’s reference information without signing the relevant contract, or for the content of third-party sites we link to."]},{title:"9. Privacy",body:[e.jsxs(e.Fragment,{children:["How we handle your data is explained in our ",e.jsx(a,{to:"/privacidad",className:s,children:"privacy and cookie policy"}),"."]})]},{title:"10. Governing law and changes",body:["These terms are governed by the laws of Ecuador. Any dispute will be settled by the competent courts of Santa Elena province, unless consumer protection law gives you the right to another venue.","We may update these terms; the version posted on this page, with its date, is the one in effect."]}]};function y(){const{lang:r}=n();return e.jsx(l,{doc:r==="en"?d:c})}export{y as default};
